// Respuesta simple para chat casual
const data = $input.item.json;

const casualPrompt = `Eres un asistente amigable de una libreria.

RESPONDE EN FORMATO JSON:
{
  "thoughts": ["paso 1", "paso 2"],
  "response": "Tu respuesta en Markdown"
}

MENSAJE DEL USUARIO:
${data.userMessage}

CONTEXTO PREVIO:
${JSON.stringify(data.conversationContext || [])}

Responde de forma breve y amigable. Menciona que tambien puedes ayudar con recomendaciones de libros.`;

return {
  ...data,
  casualPrompt: JSON.stringify({
    model: "llama-3.3-70b-versatile",
    temperature: 0.7,
    max_tokens: 300,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: "You are a friendly assistant. Respond ONLY with JSON." },
      { role: "user", content: casualPrompt }
    ]
  })
};

// Parsear respuesta de chat casual
const previousData = $('Construir Prompt Casual').item.json;
const groqResponse = $input.item.json;
const content = groqResponse.choices[0].message.content.trim();

let parsedResponse;
try {
  parsedResponse = JSON.parse(content);
} catch (error) {
  parsedResponse = {
    thoughts: ['Respuesta casual generada'],
    response: content
  };
}

return {
  userId: previousData.userId,
  conversationId: previousData.conversationId,
  messageId: previousData.messageId,
  content: parsedResponse.response || content,
  metadata: {
    thoughts: parsedResponse.thoughts || [],
    recommendations: [],
    used_querys: [],
    intentType: 'casual_chat'
  }
};

// Respuesta para out of scope
const data = $input.item.json;

return {
  userId: data.userId,
  conversationId: data.conversationId,
  messageId: data.messageId,
  content: "Lo siento, solo puedo ayudarte con recomendaciones de libros y preguntas relacionadas con nuestra biblioteca. ¿Puedo ayudarte a encontrar algun libro?",
  metadata: {
    thoughts: ["Mensaje fuera del alcance del asistente"],
    recommendations: [],
    used_querys: [],
    intentType: 'out_of_scope'
  }
};

// Los datos del webhook POST están en $json.body
const payload = $json.body;  // ← CAMBIO CLAVE

// Validar que exista userMessage
if (!payload || !payload.userMessage) {
  throw new Error('userMessage is missing from webhook payload');
}

const userMessage = payload.userMessage.toLowerCase();

let intentType = 'out_of_scope';
let confidence = 0;

// Keywords para book recommendation
const bookKeywords = [
  'libro', 'libros', 'recomienda', 'recomendación', 'leer', 'lectura',
  'autor', 'novela', 'cuento', 'ficción', 'fantasía', 'romance', 
  'ciencia ficción', 'misterio', 'thriller', 'bestseller'
];

// Keywords para casual chat
const casualKeywords = [
  'hola', 'hey', 'buenos días', 'buenas tardes', 'buenas noches',
  'qué tal', 'cómo estás', 'gracias', 'adiós', 'hasta luego'
];

// Check book recommendation
const bookMatches = bookKeywords.filter(keyword => 
  userMessage.includes(keyword)
).length;

// Check casual chat
const casualMatches = casualKeywords.filter(keyword => 
  userMessage.includes(keyword)
).length;

if (bookMatches > 0) {
  intentType = 'book_recommendation';
  confidence = bookMatches / bookKeywords.length;
} else if (casualMatches > 0 || userMessage.length < 20) {
  intentType = 'casual_chat';
  confidence = 0.8;
}

// Retornar TODOS los campos originales + los nuevos
return {
  userId: payload.userId,
  conversationId: payload.conversationId,
  messageId: payload.messageId,
  userMessage: payload.userMessage,
  baseUrl: payload.baseUrl,
  intentType,
  confidence
};

// Este nodo recibe los datos de Firestore
const firestoreData = $input.item.json;

// Transformar mensajes de Firestore a formato de contexto
const messages = firestoreData.documents || [];
const conversationContext = messages
  .reverse() // Orden cronológico
  .map(doc => ({
    role: doc.fields.role.stringValue,
    content: doc.fields.content.stringValue
  }))
  .filter(msg => msg.role === 'user' || msg.role === 'assistant');

// Obtener datos del nodo "Detectar Intención" por nombre
const detectNode = $("Detectar Intención1").item.json;

// Extraer campos originales
const userId = detectNode.userId || null;
const conversationId = detectNode.conversationId || null;
const messageId = detectNode.messageId || null;
const userMessage = detectNode.userMessage || null;
const intentType = detectNode.intentType || 'book_recommendation';
const baseUrl = detectNode.baseUrl || 'http://localhost:4200';

// Validar que tenemos userId
if (!userId) {
  throw new Error(`userId not found. DetectNode data: ${JSON.stringify(detectNode)}`);
}

// Retornar TODO combinado
return {
  userId,
  conversationId,
  messageId,
  userMessage,
  intentType,
  baseUrl,
  conversationContext
};

// Obtener datos del nodo anterior (Ejecutar SQL devuelve array de resultados)
const sqlResults = $input.all();
const previousData = $('Construir el Prompt1').first().json;

// Formatear lista de libros
const books = sqlResults.map(item => ({
  id: item.json.id,
  title: item.json.title,
  author: item.json.author,
  description: item.json.description,
  coverUrl: item.json.cover_image || item.json.cover_url
}));

// Retornar con todos los datos originales
return {
  userId: previousData.userId,
  conversationId: previousData.conversationId,
  messageId: previousData.messageId,
  userMessage: previousData.userMessage,
  baseUrl: previousData.baseUrl,
  intentType: previousData.intentType,
  conversationContext: previousData.conversationContext || [],
  sqlQuery: $('Code in JavaScript').first().json.sqlQuery,
  sqlThoughts: $('Code in JavaScript').first().json.thoughts,
  listaLibros: books,
  startTime: Date.now()
};

const data = $input.item.json;

// --- AQUI ESTA LA MAGIA DEL FORMATO VISUAL ---
const systemPrompt = `Eres un asistente experto en recomendacion de libros.

RESPONDE EN FORMATO JSON con esta estructura exacta:
{
  "thoughts": [
    "analisis del mensaje del usuario",
    "criterios de seleccion",
    "razonamiento de las recomendaciones"
  ],
  "response": "Tu respuesta en formato Markdown estricto",
  "bookIds": [1, 5, 12]
}

FORMATO VISUAL OBLIGATORIO (campo response):
- Usa UNICAMENTE Markdown.
- Máximo 5 recomendaciones.
- Si el libro tiene 'cover_url', DEBES mostrar la imagen.

ESTRUCTURA VISUAL PARA CADA LIBRO (Usa este template exacto):

![Portada]({cover_url})
### 📖 **{Titulo}**
*De {Autor}*

{Breve descripción atractiva de 2-3 lineas}

👉 **[Ver ficha y detalles](${data.baseUrl}/book-details/{ID})**

---

LENGUAJE:
- Responde en español.
- Tono amigable, experto y conciso.

ESTRUCTURA DEL MENSAJE:
1. Saludo breve y empático.
2. "He encontrado estas joyas para ti:" (o similar).
3. Lista de libros con el formato visual de arriba.
4. Pregunta de cierre (ej: "¿Te llama la atención alguno?").`;

const userPrompt = `CONTEXTO DE LA CONVERSACION:
${JSON.stringify(data.conversationContext || [])}

MENSAJE DEL USUARIO:
${data.userMessage}

LIBROS DISPONIBLES (Datos crudos de SQL):
${JSON.stringify(data.listaLibros)}
IMPORTANTISIMO: Usa el campo 'cover_url' de estos datos para las imagenes. Si es null, no pongas la linea de la imagen.

ANALISIS PREVIO:
${JSON.stringify(data.sqlThoughts || [])}

GENERA TU RESPUESTA JSON AHORA:`;

return {
  ...data,
  responsePrompt: JSON.stringify({
    model: "llama-3.3-70b-versatile",
    temperature: 0.7,
    max_tokens: 2000,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ]
  })
};

// Obtener datos previos
const previousData = $('Construir Prompts1').item.json;

// Extraer respuesta de Groq
const groqResponse = $input.item.json;
const content = groqResponse.choices[0].message.content.trim();

// Parsear JSON estructurado
let parsedResponse;
try {
  parsedResponse = JSON.parse(content);
} catch (error) {
  console.error('Error parsing JSON:', error);
  parsedResponse = {
    thoughts: ['Error al generar thoughts estructurados'],
    response: content,
    bookIds: []
  };
}

// Combinar thoughts del SQL generation con thoughts del response
const allThoughts = [
  ...((previousData.sqlThoughts || []).map(t => `[SQL] ${t}`)),
  ...((parsedResponse.thoughts || []).map(t => `[Response] ${t}`))
];

// Extraer IDs de libros recomendados
let recommendations = (parsedResponse.bookIds || []).map(id => id.toString());

// Si no hay bookIds en el response, usar todos los de listaLibros
if (recommendations.length === 0 && previousData.listaLibros) {
  recommendations = previousData.listaLibros.slice(0, 5).map(b => b.id.toString());
}

return {
  userId: previousData.userId,
  conversationId: previousData.conversationId,
  messageId: previousData.messageId,
  content: parsedResponse.response || content,
  metadata: {
    thoughts: allThoughts,
    recommendations,
    used_querys: [previousData.sqlQuery],
    intentType: 'book_recommendation',
    processingTime: Date.now() - (previousData.startTime || Date.now())
  }
};

