// El Error Trigger expone información del error
const errorData = $input.item.json;
const errorMessage = errorData.error?.message || 'Error desconocido';

// Intentar obtener datos del workflow
let userId = null;
let conversationId = null;
let messageId = null;

try {
  // Buscar en el nodo Webhook
  const webhookData = $('Webhook1').item.json;
  if (webhookData && webhookData.body) {
    userId = webhookData.body.userId;
    conversationId = webhookData.body.conversationId;
    messageId = webhookData.body.messageId;
  }
} catch (e) {
  console.log('No se pudieron obtener datos del webhook');
}

try {
  // Buscar en Detectar Intención como fallback
  const detectData = $('Detectar Intención1').item.json;
  if (detectData) {
    userId = userId || detectData.userId;
    conversationId = conversationId || detectData.conversationId;
    messageId = messageId || detectData.messageId;
  }
} catch (e) {
  console.log('No se pudieron obtener datos de Detectar Intención');
}

// Si no tenemos los datos, intentar extraer del error mismo
if (!userId && errorData.node) {
  console.log('Warning: No se encontraron userId, conversationId o messageId en el workflow');
}

return {
  userId: userId || '',
  conversationId: conversationId || '',
  messageId: messageId || '',
  errorContent: `Lo siento, ocurrio un error: ${errorMessage}. Por favor, intenta de nuevo.`
};

// La respuesta de Groq está en choices[0].message.content como string JSON
const groqResponse = $input.item.json;

// Extraer el content (que es un string JSON)
const contentString = groqResponse.choices[0].message.content;

// Parsear el JSON
let parsedContent;
try {
  parsedContent = JSON.parse(contentString);
} catch (error) {
  throw new Error(`Error parsing Groq response: ${error.message}. Content: ${contentString}`);
}

// Extraer los campos que necesitamos
const sqlQuery = parsedContent.sqlQuery || null;
const thoughts = parsedContent.thoughts || [];

// Validar que sqlQuery existe
if (!sqlQuery) {
  throw new Error(`No SQL query found in response. Parsed content: ${JSON.stringify(parsedContent)}`);
}

// Retornar todos los datos originales + los parseados
return {
  userId: $json.userId || groqResponse.userId,
  conversationId: $json.conversationId || groqResponse.conversationId,
  messageId: $json.messageId || groqResponse.messageId,
  userMessage: $json.userMessage || groqResponse.userMessage,
  baseUrl: $json.baseUrl || groqResponse.baseUrl,
  intentType: $json.intentType || groqResponse.intentType,
  sqlQuery: sqlQuery,
  thoughts: thoughts,
  groqRawResponse: contentString  // Para debugging
};

